#!/usr/bin/env python3
"""Download every order page and the customer record for each shipped order.

Raw responses are written under /tmp/recon-data. Re-running resumes: anything
already on disk is not fetched again.
"""
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
DATA = "/tmp/recon-data"
PAGES = os.path.join(DATA, "pages")
CUSTOMERS = os.path.join(DATA, "customers")
MAX_ATTEMPTS = 40

os.makedirs(PAGES, exist_ok=True)
os.makedirs(CUSTOMERS, exist_ok=True)
LOG = open(os.path.join(DATA, "requests.log"), "a")
TOKEN = {"value": None}


def log(msg):
    LOG.write(f"{time.strftime('%H:%M:%S')} {msg}\n")
    LOG.flush()


def issue_token():
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        TOKEN["value"] = json.loads(r.read())["token"]
    log(f"issued token {TOKEN['value']}")


def send(path, auth):
    headers = {}
    if auth:
        if TOKEN["value"] is None:
            issue_token()
        headers["Authorization"] = "Bearer " + TOKEN["value"]
    req = urllib.request.Request(BASE + path, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.headers, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read().decode("utf-8", "replace")


def get(path, auth=True):
    """Return (200, parsed JSON) or (404, body text).

    Retries through token expiry, rate-limit waits and transient failures. Exits on
    any response it does not recognise, so the raw response can be read first.
    """
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            status, headers, body = send(path, auth)
        except OSError as exc:  # refused connections, timeouts
            log(f"{path} attempt {attempt}: transport error {exc!r}")
            time.sleep(min(2 * attempt, 10))
            continue
        hdrs = {k.lower(): v for k, v in headers.items()}
        if status == 200:
            try:
                return 200, json.loads(body)
            except ValueError:
                log(f"{path} attempt {attempt}: 200 with non-JSON body {body[:300]!r}")
                time.sleep(1)
                continue
        log(f"{path} attempt {attempt}: HTTP {status} headers={hdrs} body={body[:300]!r}")
        if status == 404:
            return 404, body
        if status in (401, 403) and auth:
            TOKEN["value"] = None  # the next attempt fetches a fresh token
            continue
        if "retry-after" in hdrs:
            try:
                wait = float(hdrs["retry-after"])
            except ValueError:
                sys.exit(f"stopping: unparseable Retry-After on {path}; see {LOG.name}")
            time.sleep(wait + 0.5)
            continue
        if status >= 500:
            time.sleep(min(2 * attempt, 10))
            continue
        sys.exit(f"stopping: unhandled HTTP {status} for {path}; see {LOG.name}")
    sys.exit(f"stopping: gave up on {path} after {MAX_ATTEMPTS} attempts; see {LOG.name}")


def save(path, obj):
    with open(path, "w") as f:
        json.dump(obj, f)


def fetch_pages():
    status, first = get("/orders?page=1")
    if status != 200 or "items" not in first:
        sys.exit(f"stopping: first orders page unusable: {str(first)[:300]}")
    total = first["total_pages"]
    log(f"total_pages reported as {total}")
    for page in range(1, total + 1):
        out = os.path.join(PAGES, f"page-{page:03d}.json")
        if os.path.exists(out):
            continue
        status, data = get(f"/orders?page={page}")
        if status != 200 or "items" not in data:
            sys.exit(f"stopping: page {page} is not an item list: {str(data)[:300]}")
        save(out, data)
        log(f"page {page}: {len(data['items'])} items, page field={data.get('page')}, "
            f"total_pages={data.get('total_pages')}, next={data.get('next')!r}")
    return total


def shipped_customer_ids():
    ids = set()
    for name in sorted(os.listdir(PAGES)):
        with open(os.path.join(PAGES, name)) as f:
            for item in json.load(f)["items"]:
                if item.get("status") == "shipped":
                    ids.add(item.get("customer_id"))
    return ids


def fetch_customers(ids):
    for cid in sorted(ids, key=str):
        out = os.path.join(CUSTOMERS, f"{cid}.json")
        if os.path.exists(out):
            continue
        status, data = get(f"/customers/{cid}")
        save(out, {"http_status": status, "body": data})
        log(f"customer {cid}: HTTP {status}")


if __name__ == "__main__":
    total = fetch_pages()
    ids = shipped_customer_ids()
    log(f"{len(ids)} distinct customer ids on shipped orders")
    fetch_customers(ids)
    print(f"pages: {total}; customer ids: {len(ids)}; data in {DATA}")

